import{_ as o,o as r,c as s,a2 as e}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"我的最愛","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/settings/favorites.md","filePath":"zh-HK/user-guide/settings/favorites.md","lastUpdated":1787586465000}'),a={name:"zh-HK/user-guide/settings/favorites.md"};function n(i,t,l,g,d,c){return r(),s("div",null,[...t[0]||(t[0]=[e('<h1 id="我的最愛" tabindex="-1">我的最愛 <a class="header-anchor" href="#我的最愛" aria-label="Permalink to &quot;我的最愛&quot;">​</a></h1><p>我的最愛用於將你最高頻使用的資料夾、檔案、腳本或網頁 URL 固定下來，賦予專屬的自訂名稱與最高檢索優先級。設定頁面路徑為<strong>設定 → 我的最愛</strong>。</p><h2 id="_1-新增收藏項目" tabindex="-1">1. 新增收藏項目 <a class="header-anchor" href="#_1-新增收藏項目" aria-label="Permalink to &quot;1. 新增收藏項目&quot;">​</a></h2><p>在頁面上方的新增表單中：</p><ul><li><strong>顯示名稱</strong>：自訂名稱（可選）。若留空且目標為本機路徑，系統會自動使用目標檔案或資料夾的檔案名稱作為預設名稱。</li><li><strong>目標路徑</strong>：支援輸入本機檔案/目錄的絕對路徑，或以 <code>http://</code> / <code>https://</code> 開頭的完整網頁網址。</li><li><strong>瀏覽選取</strong>：按一下<strong>瀏覽資料夾</strong>或<strong>瀏覽檔案</strong>按鈕可直接調用原生檔案選取器，免去手動輸入路徑的繁瑣。</li><li><strong>新增</strong>：填入有效路徑後按一下<strong>新增</strong>按鈕即可將該項存入收藏列表。</li></ul><h2 id="_2-列表管理與拖曳排序" tabindex="-1">2. 列表管理與拖曳排序 <a class="header-anchor" href="#_2-列表管理與拖曳排序" aria-label="Permalink to &quot;2. 列表管理與拖曳排序&quot;">​</a></h2><p>下方列表集中展示所有已新增的收藏項目，支援細緻的排序與維護：</p><ul><li><strong>六點拖曳手柄排序</strong>：每一行左側均配有六點拖曳手柄，你可以按住手柄直接上下拖動調整項目順序，亦可按一下右側的<strong>向上移動</strong> / <strong>向下移動</strong>按鈕微調。這裡的排列順序直接決定了該收藏項目在搜尋結果與快速導覽選單中的先後次序。</li><li><strong>編輯此項</strong>：按一下後將該收藏項目的資料重新載入至上方表單，修改完成後按一下儲存即可更新。</li><li><strong>刪除此項</strong>：從我的最愛中安全移除該項目。</li></ul><h2 id="_3-搜尋召回與視覺呈現" tabindex="-1">3. 搜尋召回與視覺呈現 <a class="header-anchor" href="#_3-搜尋召回與視覺呈現" aria-label="Permalink to &quot;3. 搜尋召回與視覺呈現&quot;">​</a></h2><ul><li><strong>專屬星標徽標（★）</strong>：在快速視窗或主搜尋視窗中檢索到收藏項目時，結果旁會顯示醒目的 <strong>★</strong> 星標徽標。</li><li><strong>自訂別名搜尋</strong>：你可以為複雜的路徑起一個簡短好記的顯示名稱（例如將 <code>D:\\Workspace\\2026\\Q1\\Financial\\Summary.xlsx</code> 命名為 <code>財務總表</code>）。在搜尋框中輸入 <code>cwzb</code> 即可透過拼音別名秒級召回該檔案。</li><li><strong>多端聚合呈現</strong>：所有收藏項目會自動同步呈現在<a href="./../hotkeys.html#3-快速導覽滑鼠觸發"><strong>滑鼠快速導覽</strong></a>選單與<a href="./quick-panel.html#4-外掛模組標籤plugin-tabs"><strong>快速面板</strong></a>的「我的最愛」標籤中，按一下即可秒開。</li></ul>',10)])])}const _=o(a,[["render",n]]);export{u as __pageData,_ as default};
